package br.com.onda;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.graphics.*;import android.hardware.*;import android.media.*;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;import java.util.*;import java.util.concurrent.*;
/** Optional foreground tests; audio, recording and sensor listeners are released on leaving. */
public class DeviceDiagnosticsActivity extends Activity {
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private final Handler main=new Handler(Looper.getMainLooper());private final LinkedHashMap<String,String> results=new LinkedHashMap<>();private final LinkedHashMap<String,TextView> fields=new LinkedHashMap<>();
 private TextView status,testStatus;private LinearLayout details;private Button refresh,share;private DeviceReport report;private boolean closed,loading;private AlertDialog testDialog;private ToneGenerator tone;private MediaRecorder recorder;private MediaPlayer playback;private File recording;private int testGeneration;private SensorManager sensors;private SensorEventListener sensorListener;private AudioManager audio;private AudioFocusRequest focus;private Vibrator vibrator;private int events;private long lastEvent;
 @Override public void onCreate(Bundle state){super.onCreate(state);if(state!=null){ArrayList<String> keys=state.getStringArrayList("testKeys"),values=state.getStringArrayList("testValues");if(keys!=null&&values!=null&&keys.size()==values.size())for(int i=0;i<keys.size();i++)results.put(keys.get(i),values.get(i));}sensors=(SensorManager)getSystemService(SENSOR_SERVICE);audio=(AudioManager)getSystemService(AUDIO_SERVICE);vibrator=(Vibrator)getSystemService(VIBRATOR_SERVICE);
  LinearLayout root=column();Ui.background(root);root.setOnApplyWindowInsetsListener((v,i)->{root.setPadding(Ui.dp(this,16),Ui.dp(this,10)+i.getSystemWindowInsetTop(),Ui.dp(this,16),Ui.dp(this,10)+i.getSystemWindowInsetBottom());return i;});setContentView(root);LinearLayout header=new LinearLayout(this);header.setGravity(Gravity.CENTER_VERTICAL);Button back=Ui.button(this,"‹",v->finish());back.setContentDescription("Voltar do diagnóstico");header.addView(back,new LinearLayout.LayoutParams(Ui.dp(this,48),Ui.dp(this,48)));TextView title=Ui.text(this,"Meu smartphone",22,Ui.TEXT);title.setMaxLines(1);title.setEllipsize(android.text.TextUtils.TruncateAt.END);header.addView(title,new LinearLayout.LayoutParams(0,-2,1));root.addView(header);
  ScrollView scroll=new ScrollView(this);LinearLayout body=column();scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));body.addView(Ui.text(this,"Informações do Android e testes que você inicia. Sem monitoramento contínuo ou envio de dados. Alguns resultados dependem do aparelho e das permissões.",14,Ui.MUTED));status=Ui.text(this,"Preparando leitura…",14,Ui.CYAN);status.setPadding(0,Ui.dp(this,10),0,Ui.dp(this,10));body.addView(status);refresh=Ui.button(this,"Atualizar informações",v->collect());body.addView(refresh,new LinearLayout.LayoutParams(-1,-2));details=column();body.addView(details,new LinearLayout.LayoutParams(-1,-2));
  Ui.Section tests=new Ui.Section(this,"Testes manuais",true);tests.content.addView(Ui.text(this,"Resultados de tela, som, microfone e vibração são observações suas, não um diagnóstico automático de defeitos. Interrompa se houver desconforto.",13,Ui.MUTED));tests.content.addView(Ui.button(this,"Testar cores da tela",v->screen()));tests.content.addView(Ui.button(this,"Testar toque",v->touch()));tests.content.addView(Ui.button(this,"Testar som • 2 segundos",v->sound()));tests.content.addView(Ui.button(this,"Testar microfone • 4 segundos",v->microphone()));tests.content.addView(Ui.button(this,"Testar vibração",v->vibration()));tests.content.addView(Ui.button(this,"Testar um sensor • até 8 segundos",v->sensor()));testStatus=Ui.text(this,"Nenhum teste concluído.",13,Ui.CYAN);tests.content.addView(testStatus);body.addView(tests);
  share=Ui.button(this,"Compartilhar relatório",v->{if(report!=null)try{startActivity(Intent.createChooser(new Intent(Intent.ACTION_SEND).setType("text/plain").putExtra(Intent.EXTRA_TEXT,report.text(results)),"Compartilhar diagnóstico"));}catch(ActivityNotFoundException e){status.setText("Nenhum aplicativo para compartilhar disponível.");}});share.setEnabled(false);body.addView(share,new LinearLayout.LayoutParams(-1,-2));body.addView(Ui.text(this,"O Android não permite verificar todos os componentes, listar todos os apps ou determinar com precisão a capacidade real e o desgaste da bateria. Sem leitura de IMEI, número de série, contas ou identificação de redes. Este recurso não substitui assistência técnica. Leituras e testes param ao sair desta tela.",13,Ui.MUTED));updateResults();collect();
 }
 private LinearLayout column(){LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);return box;}
 private void collect(){if(loading)return;loading=true;refresh.setEnabled(false);status.setText("Lendo informações disponíveis…");worker.execute(()->{try{DeviceReport snapshot=DeviceReport.collect(this);main.post(()->{if(closed)return;report=snapshot;loading=false;refresh.setEnabled(true);share.setEnabled(true);if(fields.isEmpty())for(Map.Entry<String,String> entry:snapshot.sections.entrySet()){Ui.Section section=new Ui.Section(this,entry.getKey(),fields.isEmpty());TextView text=Ui.text(this,entry.getValue(),14,Ui.TEXT);text.setTextIsSelectable(true);section.content.addView(text);details.addView(section,new LinearLayout.LayoutParams(-1,-2));fields.put(entry.getKey(),text);}else for(Map.Entry<String,String> entry:snapshot.sections.entrySet())fields.get(entry.getKey()).setText(entry.getValue());status.setText("Leitura concluída. Atualize quando quiser; não há consulta contínua.");});}catch(Exception e){main.post(()->{if(!closed){loading=false;refresh.setEnabled(true);status.setText("Parte das informações não foi liberada pelo Android. Tente atualizar.");}});}});}
 private void result(String key,String value){results.put(key,value);updateResults();}
 private void updateResults(){StringBuilder s=new StringBuilder();for(Map.Entry<String,String> e:results.entrySet())s.append(e.getKey()).append(": ").append(e.getValue()).append("\n");if(testStatus!=null)testStatus.setText(s.length()==0?"Nenhum teste concluído.":s.toString());}
 private boolean audioFocus(){final int generation=testGeneration;focus=new AudioFocusRequest.Builder(AudioManager.AUDIOFOCUS_GAIN_TRANSIENT).setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION).build()).setOnAudioFocusChangeListener(change->{if(change<0&&generation==testGeneration)stopTests();}).build();if(audio.requestAudioFocus(focus)!=AudioManager.AUDIOFOCUS_REQUEST_GRANTED){focus=null;status.setText("Outra reprodução impediu este teste. Pause o áudio e tente novamente.");return false;}return true;}
 private void screen(){stopTests();int[] colors={Color.WHITE,Color.BLACK,Color.RED,Color.GREEN,Color.BLUE};int[] position={0};TextView panel=new TextView(this);panel.setGravity(Gravity.CENTER);panel.setTextSize(16);panel.setTextColor(Color.GRAY);panel.setText("Toque para mudar a cor • observe pontos, manchas ou linhas");panel.setBackgroundColor(colors[0]);panel.setMinHeight(Ui.dp(this,340));testDialog=new AlertDialog.Builder(this).setTitle("Cores da tela").setView(panel).setPositiveButton("Observei normalmente",(d,w)->result("Tela","Usuário não observou anomalias nas cores exibidas")).setNegativeButton("Observei alteração",(d,w)->result("Tela","Usuário observou alteração; não determina a causa")).setNeutralButton("Cancelar",null).create();panel.setOnClickListener(v->{position[0]=(position[0]+1)%colors.length;panel.setBackgroundColor(colors[position[0]]);});testDialog.show();}
 private void touch(){stopTests();TouchSurface surface=new TouchSurface(this);testDialog=new AlertDialog.Builder(this).setTitle("Toque nas 9 áreas").setView(surface).setPositiveButton("Concluir",(d,w)->result("Toque",surface.covered()+" de 9 áreas alcançadas; até "+surface.pointers+" toque(s) simultâneo(s) recebido(s). Não avalia toda a sensibilidade.")).setNegativeButton("Cancelar",null).show();}
 static final class TouchSurface extends View{final boolean[] cells=new boolean[9];int pointers;final Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);TouchSurface(Context c){super(c);setMinimumHeight(Ui.dp(c,360));setContentDescription("Grade de nove áreas para testar o toque");}@Override protected void onDraw(Canvas canvas){for(int i=0;i<9;i++){paint.setColor(cells[i]?0xFF1B8F81:0xFF243047);float left=(i%3)*getWidth()/3f,top=(i/3)*getHeight()/3f;canvas.drawRect(left+3,top+3,left+getWidth()/3f-3,top+getHeight()/3f-3,paint);paint.setColor(Color.WHITE);paint.setTextSize(Ui.dp(getContext(),20));canvas.drawText(String.valueOf(i+1),left+getWidth()/6f,top+getHeight()/6f,paint);}}@Override public boolean onTouchEvent(MotionEvent event){pointers=Math.max(pointers,event.getPointerCount());for(int i=0;i<event.getPointerCount();i++){int x=(int)(event.getX(i)*3/Math.max(1,getWidth())),y=(int)(event.getY(i)*3/Math.max(1,getHeight()));if(x>=0&&x<3&&y>=0&&y<3)cells[y*3+x]=true;}invalidate();if(event.getActionMasked()==MotionEvent.ACTION_UP)performClick();return true;}@Override public boolean performClick(){super.performClick();return true;}int covered(){int n=0;for(boolean cell:cells)if(cell)n++;return n;}}
 private void sound(){stopTests();if(!audioFocus())return;try{tone=new ToneGenerator(AudioManager.STREAM_MUSIC,25);tone.startTone(ToneGenerator.TONE_PROP_BEEP2,2000);int generation=testGeneration;main.postDelayed(()->{if(generation==testGeneration){if(tone!=null){tone.release();tone=null;}abandonFocus();}},2100);testDialog=new AlertDialog.Builder(this).setTitle("Teste de som").setMessage("Um sinal toca por até 2 segundos na saída de áudio atual. Não altera seu volume. Para testar o alto-falante, desconecte fones. Você ouviu o sinal?").setPositiveButton("Ouvi",(d,w)->result("Som","Usuário ouviu o sinal na saída atual")).setNegativeButton("Não ouvi",(d,w)->result("Som","Usuário não ouviu; confira volume e saída antes de concluir defeito")).setNeutralButton("Cancelar",null).show();testDialog.setOnDismissListener(d->stopTests());}catch(RuntimeException e){stopTests();status.setText("O Android não permitiu iniciar o som.");}}
 private void vibration(){stopTests();if(vibrator==null||!vibrator.hasVibrator()){result("Vibração","Vibrador não informado pelo Android");return;}try{vibrator.vibrate(VibrationEffect.createOneShot(300,VibrationEffect.DEFAULT_AMPLITUDE));testDialog=new AlertDialog.Builder(this).setTitle("Vibração").setMessage("Você sentiu a vibração? As configurações do sistema podem limitar este teste.").setPositiveButton("Senti",(d,w)->result("Vibração","Usuário percebeu a vibração")).setNegativeButton("Não senti",(d,w)->result("Vibração","Usuário não percebeu; verifique também as configurações do Android")).setNeutralButton("Cancelar",null).show();}catch(SecurityException e){status.setText("O Android bloqueou a vibração.");}}
 private void microphone(){stopTests();if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},9751);return;}if(!audioFocus())return;try{recording=File.createTempFile("onda-mic-test-",".m4a",getCacheDir());recorder=new MediaRecorder();recorder.setAudioSource(MediaRecorder.AudioSource.MIC);recorder.setOutputFormat(MediaRecorder.OutputFormat.MPEG_4);recorder.setAudioEncoder(MediaRecorder.AudioEncoder.AAC);recorder.setAudioSamplingRate(16000);recorder.setAudioEncodingBitRate(32000);recorder.setOutputFile(recording.getPath());recorder.setMaxDuration(4000);int generation=testGeneration;recorder.setOnInfoListener((m,what,extra)->{if(what==MediaRecorder.MEDIA_RECORDER_INFO_MAX_DURATION_REACHED&&generation==testGeneration)finishRecording(generation);});recorder.prepare();recorder.start();status.setText("Gravando por até 4 segundos. Fale perto do microfone. A gravação é temporária e local.");main.postDelayed(()->finishRecording(generation),4100);}catch(Exception e){stopTests();status.setText("Não foi possível gravar. Confira a permissão, o uso do microfone por outro app e as restrições do Android.");}}
 private void finishRecording(int generation){if(generation!=testGeneration||recorder==null)return;MediaRecorder current=recorder;recorder=null;try{current.stop();}catch(RuntimeException e){current.release();stopTests();status.setText("A gravação não pôde ser concluída. Tente novamente.");return;}current.release();abandonFocus();status.setText("Gravação temporária pronta; ouça para conferir o microfone.");testDialog=new AlertDialog.Builder(this).setTitle("Microfone").setMessage("A gravação foi feita no celular e será removida ao fechar este teste. Toque em Ouvir e confira a voz.").setPositiveButton("Ouvir",null).setNegativeButton("Encerrar",(d,w)->stopTests()).create();testDialog.setOnDismissListener(d->{if(playback==null&&recorder==null)stopTests();});testDialog.setOnShowListener(d->testDialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->playRecording()));testDialog.show();}
 private void playRecording(){if(recording==null||!recording.isFile())return;if(playback!=null)return;if(!audioFocus())return;try{playback=new MediaPlayer();playback.setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_SPEECH).build());playback.setDataSource(recording.getPath());playback.setOnCompletionListener(p->{p.release();playback=null;abandonFocus();if(testDialog!=null){testDialog.setOnDismissListener(null);testDialog.dismiss();}testDialog=new AlertDialog.Builder(this).setTitle("Conferir microfone").setMessage("A sua voz ficou audível na gravação?").setPositiveButton("Sim",(d,w)->result("Microfone","Usuário ouviu a própria gravação local")).setNegativeButton("Não",(d,w)->result("Microfone","Usuário não ouviu a própria voz; resultado não identifica a causa")).setNeutralButton("Cancelar",null).show();testDialog.setOnDismissListener(d->stopTests());});playback.prepare();playback.start();}catch(Exception e){stopTests();status.setText("Não foi possível reproduzir a gravação.");}}
 private void sensor(){stopTests();List<Sensor> available=new ArrayList<>();for(int type:new int[]{Sensor.TYPE_ACCELEROMETER,Sensor.TYPE_GYROSCOPE,Sensor.TYPE_LIGHT,Sensor.TYPE_PROXIMITY}){Sensor s=sensors.getDefaultSensor(type);if(s!=null)available.add(s);}if(available.isEmpty()){result("Sensores","Nenhum dos sensores de teste foi anunciado");return;}String[] labels=new String[available.size()];for(int i=0;i<labels.length;i++)labels[i]=available.get(i).getName();testDialog=new AlertDialog.Builder(this).setTitle("Escolher sensor").setItems(labels,(d,i)->startSensor(available.get(i))).setNegativeButton("Cancelar",null).show();}
 private void startSensor(Sensor sensor){stopTests();events=0;lastEvent=0;int generation=testGeneration;TextView readings=Ui.text(this,"Aguardando leitura… mova o aparelho ou varie a luz/proximidade, conforme o sensor.",16,Ui.TEXT);readings.setPadding(Ui.dp(this,20),Ui.dp(this,16),Ui.dp(this,20),Ui.dp(this,16));testDialog=new AlertDialog.Builder(this).setTitle(sensor.getName()).setView(readings).setNegativeButton("Interromper",(d,w)->stopTests()).create();sensorListener=new SensorEventListener(){public void onAccuracyChanged(Sensor s,int accuracy){}public void onSensorChanged(SensorEvent event){if(generation!=testGeneration)return;events++;long now=SystemClock.elapsedRealtime();if(now-lastEvent<200)return;lastEvent=now;String unit=sensor.getType()==Sensor.TYPE_ACCELEROMETER?"m/s²":sensor.getType()==Sensor.TYPE_GYROSCOPE?"rad/s":sensor.getType()==Sensor.TYPE_LIGHT?"lux":"cm";StringBuilder text=new StringBuilder("Valores recebidos ("+unit+"):\n");for(int i=0;i<Math.min(3,event.values.length);i++)text.append(String.format(Locale.getDefault(),"%.2f\n",event.values[i]));text.append("Leituras: ").append(events).append("\nReceber dados não comprova a calibração.");readings.setText(text.toString());}};testDialog.setOnDismissListener(d->stopTests());testDialog.show();if(!sensors.registerListener(sensorListener,sensor,SensorManager.SENSOR_DELAY_NORMAL)){result("Sensor "+sensor.getName(),"O Android não liberou leituras");stopTests();return;}main.postDelayed(()->{if(generation==testGeneration){result("Sensor "+sensor.getName(),events>0?events+" amostras recebidas; calibração não avaliada":"Nenhuma amostra recebida; pode estar bloqueado ou indisponível");stopTests();}},8000);}
 private void abandonFocus(){if(focus!=null){audio.abandonAudioFocusRequest(focus);focus=null;}}
 private void stopTests(){testGeneration++;if(sensors!=null&&sensorListener!=null){sensors.unregisterListener(sensorListener);sensorListener=null;}if(tone!=null){tone.stopTone();tone.release();tone=null;}if(recorder!=null){try{recorder.stop();}catch(RuntimeException ignored){}recorder.release();recorder=null;}if(playback!=null){playback.release();playback=null;}if(recording!=null){recording.delete();recording=null;}if(vibrator!=null)vibrator.cancel();abandonFocus();AlertDialog dialog=testDialog;testDialog=null;if(dialog!=null){dialog.setOnDismissListener(null);dialog.dismiss();}}
 @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] grants){super.onRequestPermissionsResult(request,permissions,grants);if(request==9751){if(grants.length>0&&grants[0]==PackageManager.PERMISSION_GRANTED)microphone();else status.setText("Microfone não autorizado. Os demais testes continuam disponíveis.");}}
 @Override protected void onStop(){super.onStop();boolean active=recorder!=null||playback!=null||tone!=null||sensorListener!=null;if(active&&status!=null)status.setText("Teste interrompido ao sair da tela. Nenhum resultado automático de aprovação foi registrado.");stopTests();}
 @Override public void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);state.putStringArrayList("testKeys",new ArrayList<>(results.keySet()));state.putStringArrayList("testValues",new ArrayList<>(results.values()));}
 @Override protected void onDestroy(){closed=true;stopTests();main.removeCallbacksAndMessages(null);worker.shutdownNow();super.onDestroy();}
}
